{"name": "consignee_account_repository", "type": "code/csharp", "content": "using Logistix.ServerAPI.Data.Context;
using Logistix.ServerAPI.Models.Entity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace Logistix.ServerAPI.Data.Repository
{
    public class ConsigneeAccountRepository
    {
        private readonly IDbContextFactory<CustomerContext> _dbContextFactory;
        private readonly ILogger<ConsigneeAccountRepository> _logger;

        public ConsigneeAccountRepository(IDbContextFactory<CustomerContext> dbContextFactory, ILogger<ConsigneeAccountRepository> logger)
        {
            _dbContextFactory = dbContextFactory;
            _logger = logger;
        }

        // Add a new consignee account
        public async Task<bool> AddConsigneeAccountAsync(ConsigneeAccountEntity consigneeAccount)
        {
            if (consigneeAccount == null) throw new ArgumentNullException(nameof(consigneeAccount));

            using var context = _dbContextFactory.CreateDbContext();
            context.Set<ConsigneeAccountEntity>().Add(consigneeAccount);
            await context.SaveChangesAsync();
            return true;
        }

        // Retrieve a consignee account by ID
        public async Task<ConsigneeAccountEntity> GetConsigneeAccountByIdAsync(string accountNumber)
        {
            if (string.IsNullOrWhiteSpace(accountNumber)) throw new ArgumentException("Account number cannot be null or empty.", nameof(accountNumber));

            using var context = _dbContextFactory.CreateDbContext();
            return await context.Set<ConsigneeAccountEntity>().FirstOrDefaultAsync(c => c.AccountNumber == accountNumber);
        }

        // Retrieve all consignee accounts
        public async Task<IEnumerable<ConsigneeAccountEntity>> GetConsigneeAccountsAsync()
        {
            using var context = _dbContextFactory.CreateDbContext();
            return await context.Set<ConsigneeAccountEntity>().ToListAsync();
        }

        // Update an existing consignee account
        public async Task<bool> UpdateConsigneeAccountAsync(ConsigneeAccountEntity consigneeAccount)
        {
            if (consigneeAccount == null) throw new ArgumentNullException(nameof(consigneeAccount));

            using var context = _dbContextFactory.CreateDbContext();
            var existingAccount = await context.Set<ConsigneeAccountEntity>().FirstOrDefaultAsync(c => c.AccountNumber == consigneeAccount.AccountNumber);
            if (existingAccount == null) return false;

            context.Entry(existingAccount).CurrentValues.SetValues(consigneeAccount);

            try
            {
                await context.SaveChangesAsync();
                return true;
            }
            catch (DbUpdateConcurrencyException)
            {
                throw new InvalidOperationException("The consignee account was updated by another user.");
            }
        }

        // Delete a consignee account by Account Number
        public async Task<bool> DeleteConsigneeAccountAsync(string accountNumber)
        {
            if (string.IsNullOrWhiteSpace(accountNumber)) throw new ArgumentException("Account number cannot be null or empty.", nameof(accountNumber));

            using var context = _dbContextFactory.CreateDbContext();
            var consigneeAccount = await context.Set<ConsigneeAccountEntity>().FirstOrDefaultAsync(c => c.AccountNumber == accountNumber);
            if (consigneeAccount == null) return false;

            context.Set<ConsigneeAccountEntity>().Remove(consigneeAccount);

            try
            {
                await context.SaveChangesAsync();
                return true;
            }
            catch (DbUpdateConcurrencyException)
            {
                throw new InvalidOperationException("The consignee account was deleted or updated by another user.");
            }
        }
    }
}"}

