{"name": "customer_repository", "type": "code/csharp", "content": "using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;

namespace Logistix.WinForms.Repositories
{
    public class CustomerRepository
    {
        private readonly HttpClient _httpClient;

        public CustomerRepository(HttpClient httpClient)
        {
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        }

        // Add a new customer
        public async Task<bool> AddCustomerAsync(CustomerEntity customer)
        {
            if (customer == null) throw new ArgumentNullException(nameof(customer));

            var jsonContent = new StringContent(JsonSerializer.Serialize(customer), Encoding.UTF8, "application/json");
            var response = await _httpClient.PostAsync("/customers/add", jsonContent);

            return response.IsSuccessStatusCode;
        }

        // Get all customers
        public async Task<IEnumerable<CustomerEntity>> GetAllCustomersAsync()
        {
            var response = await _httpClient.GetAsync("/customers/all");

            if (!response.IsSuccessStatusCode) throw new Exception("Error fetching customers.");

            var jsonResponse = await response.Content.ReadAsStringAsync();
            return JsonSerializer.Deserialize<IEnumerable<CustomerEntity>>(jsonResponse, new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
        }

        // Get customer by ID
        public async Task<CustomerEntity> GetCustomerByIdAsync(Guid id)
        {
            if (id == Guid.Empty) throw new ArgumentException("Customer ID cannot be empty.", nameof(id));

            var response = await _httpClient.GetAsync($"/customers/{id}");

            if (!response.IsSuccessStatusCode) throw new Exception("Error fetching customer by ID.");

            var jsonResponse = await response.Content.ReadAsStringAsync();
            return JsonSerializer.Deserialize<CustomerEntity>(jsonResponse, new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
        }

        // Update a customer
        public async Task<bool> UpdateCustomerAsync(CustomerEntity customer)
        {
            if (customer == null) throw new ArgumentNullException(nameof(customer));

            var jsonContent = new StringContent(JsonSerializer.Serialize(customer), Encoding.UTF8, "application/json");
            var response = await _httpClient.PutAsync("/customers/update", jsonContent);

            return response.IsSuccessStatusCode;
        }

        // Update customer contacts
        public async Task<bool> UpdateCustomerContactsAsync(Guid id, string billingContactsJson)
        {
            if (id == Guid.Empty) throw new ArgumentException("Customer ID cannot be empty.", nameof(id));
            if (string.IsNullOrWhiteSpace(billingContactsJson)) throw new ArgumentException("Billing contacts JSON cannot be empty.", nameof(billingContactsJson));

            var jsonContent = new StringContent(JsonSerializer.Serialize(new { billingContactsJson }), Encoding.UTF8, "application/json");
            var response = await _httpClient.PutAsync($"/customers/{id}/contacts/update", jsonContent);

            return response.IsSuccessStatusCode;
        }

        // Mark customer as deleted
        public async Task<bool> DeleteCustomerAsync(Guid id)
        {
            if (id == Guid.Empty) throw new ArgumentException("Customer ID cannot be empty.", nameof(id));

            var response = await _httpClient.DeleteAsync($"/customers/delete/{id}");

            return response.IsSuccessStatusCode;
        }
    }
}"}

