        private void RadGridView1_CustomFiltering(object sender, GridViewCustomFilteringEventArgs e)
        {
            if (string.IsNullOrEmpty(txtFilter.Text))
            {
                e.Visible = true;
                return;
            }

            e.Visible = false;
            foreach (var cell in e.Row.Cells)
            {
                if (cell.Value != null && cell.Value.ToString().IndexOf(txtFilter.Text, StringComparison.InvariantCultureIgnoreCase) >= 0)
                {
                    e.Visible = true;
                    cell.Style.CustomizeFill = true;
                    cell.Style.DrawFill = true;
                    cell.Style.BackColor = System.Drawing.Color.FromArgb(201, 252, 254);
                }
                else
                {
                    cell.Style.Reset();
                }
            }
